public static class MacroGuiTests {
 static readonly BindingFlags Hidden=BindingFlags.Instance|BindingFlags.NonPublic;
 static int checks,layouts;static string renderOutput;
 static void Check(bool good,string label){checks++;if(!good)throw new Exception(label);}
 static object Get(MainWindow window,string name){return typeof(MainWindow).GetField(name,Hidden).GetValue(window);}
 static void Set(MainWindow window,string name,object value){typeof(MainWindow).GetField(name,Hidden).SetValue(window,value);}
 static object Invoke(MainWindow window,string method,params object[] args){return typeof(MainWindow).GetMethod(method,Hidden).Invoke(window,args);}
 static IEnumerable<T> Walk<T>(DependencyObject root)where T:DependencyObject{if(root is T)yield return(T)root;foreach(object child in LogicalTreeHelper.GetChildren(root)){var dependency=child as DependencyObject;if(dependency!=null)foreach(T value in Walk<T>(dependency))yield return value;}}
 static IEnumerable<T> Visual<T>(DependencyObject root)where T:DependencyObject{if(root is T)yield return(T)root;for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++)foreach(T value in Visual<T>(VisualTreeHelper.GetChild(root,i)))yield return value;}
 static T Tag<T>(DependencyObject root,string tag)where T:FrameworkElement{return Walk<T>(root).Single(item=>Object.Equals(item.Tag,tag));}
 static MacroDocument Document(params MacroAction[] actions){return new MacroDocument{Name="宏01",Actions=actions.ToList()};}
 static MacroAction Action(string kind){return new MacroAction{Kind=kind,Key=65,Button=1,Value=120,DelayMs=100,BeforeMs=50,X=128,Y=256};}
 static void Pump(FrameworkElement root){root.UpdateLayout();Dispatcher.CurrentDispatcher.Invoke(new System.Action(()=>{}),DispatcherPriority.Background);root.UpdateLayout();}
 static void Save(FrameworkElement root,int width,int height,string name){if(renderOutput==null)return;var bitmap=new RenderTargetBitmap(width,height,96,96,PixelFormats.Pbgra32);bitmap.Render(root);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var stream=File.Create(Path.Combine(renderOutput,name)))encoder.Save(stream);}
 static void Layout(MainWindow window,MacroDocument document,int selected,int width,string name,bool playback=false,bool recording=false) {
  Set(window,"macroPlayTask",null);Set(window,"macroRecordingHook",null);((MacroEditor)Get(window,"macroEditor")).Load(document);Set(window,"macroSelection",selected);Set(window,"macroMessage",playback?"正在软件执行 · F9 / 停止可终止":recording?"正在录制本程序外的输入 · F9 停止":"本地宏 · 尚未保存");if(playback)Set(window,"macroPlayTask",Task.FromResult(true));if(recording){Set(window,"macroRecordingHook",new MacroHookSession(false,null,null));Set(window,"macroCapture",new MacroCaptureBuffer(false));Set(window,"macroRecordingBase",document.Clone());}Invoke(window,"ShowPage","宏");((ScrollViewer)Get(window,"pageScroll")).ScrollToTop();var root=(FrameworkElement)window.Content;int height=width==1180?726:826;root.Measure(new Size(width,height));root.Arrange(new Rect(0,0,width,height));Pump(root);
  var body=Tag<Canvas>(root,"Macro.Surface");var timeline=Tag<Grid>(root,"Macro.Timeline");var parameters=Tag<Border>(root,"Macro.Parameters");var viewport=Tag<ScrollViewer>(root,"Macro.Viewport");var profile=(ComboBox)Get(window,"macroFileBox");
  Check(body.Width==1246&&body.Height==660,"original fixed macro canvas");Check(Math.Abs(body.TransformToAncestor(root).Transform(new Point()).Y-111)<1,"macro body origin111");Check(parameters.Width==303&&parameters.Height==590&&Canvas.GetLeft(parameters)==893&&Canvas.GetTop(parameters)==11,"original303x590 parameter rectangle");Check(timeline.Width==806&&timeline.Height==590&&Canvas.GetLeft(timeline)==50&&Canvas.GetTop(timeline)==11,"original timeline placement");Check(!Walk<Border>(timeline).Any(border=>border.BorderThickness.Left>0&&border.BorderThickness.Right>0&&border.BorderThickness.Top>0&&border.BorderThickness.Bottom>0),"timeline has no whole rectangular border");Check(!Walk<Image>(body).Any(),"no vendor bitmap artwork");
  Check(profile.SelectedItem is MacroDocument&&((MacroDocument)profile.SelectedItem).Name==document.Name,"profile is actual local macro name");Check(Visual<TextBlock>(profile).Any(block=>block.Text==document.Name)&&!Visual<TextBlock>(profile).Any(block=>block.Text.Contains("RogControl.")),"rendered selector displays macro name instead of object type");foreach(var block in Visual<TextBlock>(profile).Where(block=>block.Text==document.Name)){Check(block.TextTrimming==TextTrimming.CharacterEllipsis&&block.ActualWidth<=profile.ActualWidth,"long macro names stay inside selector");Check(Convert.ToString(block.ToolTip)==document.Name,"full macro name remains accessible in tooltip");}Check(profile.Height==32&&profile.MinWidth==296,"first-row macro selector dimensions");foreach(var border in Visual<Border>(profile)){var brush=border.Background as SolidColorBrush;if(brush!=null&&brush.Color.A>0)Check(brush.Color.R<80&&brush.Color.G<80&&brush.Color.B<80,"combo uses dark rendered background");}
  var record=(Button)Get(window,"macroRecordButton");var insert=(Button)Get(window,"macroInsertButton");Check(record.Width==104&&record.Height==20&&insert.Width==104&&insert.Height==20,"original compact record/insert controls");Check(Math.Abs(record.TransformToAncestor(root).Transform(new Point()).X-321)<1,"record original x321");Check(Math.Abs(record.TransformToAncestor(root).Transform(new Point()).Y-74)<1,"record original client y74");Check(record.ToolTip.ToString().Contains("F9"),"record keeps emergency-stop help");Check(!record.IsEnabled,"render-only recording disabled");Check(!Walk<TextBlock>(body).Any(block=>block.Text.Contains("本地宏")||block.Text.Contains("硬件板载")||block.Text.Contains("软件宏")),"engineering explanation removed from main canvas");
  var count=(TextBlock)Get(window,"macroCount");var duration=(TextBlock)Get(window,"macroDuration");Check(count.Text=="动作 ("+document.Actions.Count+"/100)","real count kept at timeline header");Check(duration.Text.Contains((document.DurationMs/1000.0).ToString("0.000",System.Globalization.CultureInfo.InvariantCulture)),"real total duration stays in header");Check(((Grid)Get(window,"macroTimelineEmpty")).Visibility==(document.Actions.Count==0?Visibility.Visible:Visibility.Collapsed),"empty timeline message follows actual action count");var stack=(StackPanel)Get(window,"macroParameters");Check(Walk<Grid>(stack).Any(grid=>Object.Equals(grid.Tag,"Macro.EmptyParameters"))==(selected<0),"empty parameter prompt only when no action selected");if(selected<0){Check(!Walk<TextBox>(stack).Any(),"empty parameter panel contains no name or fake parameter editor");Check(Walk<TextBlock>(stack).Any(block=>block.Text=="请选择一个项目以调整参数。"),"official empty parameter text");}
  var stop=(Button)Get(window,"macroStopButton");Check(stop.Visibility==(playback||recording?Visibility.Visible:Visibility.Collapsed)&&stop.IsEnabled==(playback||recording),"visible active stop cannot be lost in a menu");Check(((Button)Get(window,"macroSaveButton")).IsEnabled==(!playback&&!recording&&document.Actions.Count>0),"empty or active macro save unavailable");Check(((Button)Get(window,"macroCancelButton")).IsEnabled==(!playback&&!recording&&selected>=0),"cancel only affects an actual parameter edit");if(playback||recording)Check(((TextBlock)Get(window,"status")).Text.Contains("F9"),"active session still displays emergency stop status");
  foreach(var block in Walk<TextBlock>(body)){if(block.ActualWidth<=0||block.ActualHeight<=0)continue;Check(block.TextWrapping!=TextWrapping.NoWrap||block.DesiredSize.Width-block.Margin.Left-block.Margin.Right<=block.ActualWidth+1,"intrinsic body text not clipped: "+block.Text);var bounds=block.TransformToAncestor(body).TransformBounds(new Rect(0,0,block.ActualWidth,block.ActualHeight));Check(bounds.Left>=-1&&bounds.Right<=body.Width+1,"body text remains on original canvas: "+block.Text);}
  foreach(var combo in Walk<ComboBox>(body)){var ink=(SolidColorBrush)combo.Foreground;Check(ink.Color.R>150&&combo.Template!=null,"parameter combo remains dark with visible text");Check(!Visual<TextBlock>(combo).Any(block=>block.Text.Contains("RogControl.")),"parameter choice is a caption, not a type name");}if(selected>=0&&document.Actions[selected].Kind.StartsWith("key-"))Check(Visual<TextBlock>((ComboBox)Get(window,"macroKeyBox")).Any(block=>block.Text=="A"),"selected keyboard key displays its exact name");
  Save(root,width,height,name+"-"+width+".png");viewport.ScrollToRightEnd();((ScrollViewer)Get(window,"pageScroll")).ScrollToBottom();Pump(root);var boundsAfter=parameters.TransformToAncestor(root).TransformBounds(new Rect(0,0,parameters.ActualWidth,parameters.ActualHeight));Check(boundsAfter.Left>=248&&boundsAfter.Right<=width-20&&boundsAfter.Bottom<=height-20,"whole parameter frame reachable at narrow and wide sizes");foreach(string field in new[]{"macroSaveButton","macroCancelButton"}){var button=(Button)Get(window,field);var bounds=button.TransformToAncestor(root).TransformBounds(new Rect(0,0,button.ActualWidth,button.ActualHeight));Check(bounds.Left>=248&&bounds.Right<=width-20&&bounds.Bottom<=height-20,"save/cancel accessible: "+field);}
  if(width==1180)Save(root,width,height,name+"-"+width+"-right.png");Check(!window.IsVisible&&PresentationSource.FromVisual(window)==null,"no native presentation window");Check((recording?Get(window,"macroRecordingHook")!=null:Get(window,"macroRecordingHook")==null)&&Get(window,"macroPlaybackHook")==null&&Get(window,"macroRecordingTimer")==null,"only an injected unstarted recording object may exist");if(recording){var hook=Get(window,"macroRecordingHook");Check(typeof(MacroHookSession).GetField("thread",Hidden).GetValue(hook)==null&&(IntPtr)typeof(MacroHookSession).GetField("keyboardHook",Hidden).GetValue(hook)==IntPtr.Zero&&(IntPtr)typeof(MacroHookSession).GetField("mouseHook",Hidden).GetValue(hook)==IntPtr.Zero,"fake recording object has no native hook or thread");Check(Walk<TextBlock>(record).Any(block=>block.Text=="停止录制"),"record control retains explicit stop caption");stop.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(Get(window,"macroRecordingHook")==null&&!window.MacroFeaturesActive,"toolbar stop finishes injected recording without installing a hook");}var options=(ContextMenu)Invoke(window,"BuildMacroOptionsMenu");var run=options.Items.OfType<MenuItem>().Single(item=>Convert.ToString(item.Header)=="软件执行");Check(!run.IsEnabled&&run.ToolTip.ToString().Contains("F9"),"software run is in menu with stop help and disabled in render-only");if(!playback&&!recording){run.RaiseEvent(new RoutedEventArgs(MenuItem.ClickEvent));Invoke(window,"ToggleMacroRecording");Invoke(window,"OpenMacroInsertMenu");Invoke(window,"OpenMacroFileMenu");Check(Get(window,"macroPlayTask")==null&&Get(window,"macroRecordingHook")==null&&Get(window,"macroPlaybackHook")==null,"render-only manual handlers create no input session");Check(insert.ContextMenu==null,"render-only insertion does not open native popup");}
  layouts++;
 }
 [STAThread]public static int Main(string[] args){try{renderOutput=args.Length==2&&args[0]=="--render"?Path.GetFullPath(args[1]):null;if(renderOutput!=null)Directory.CreateDirectory(renderOutput);var window=new MainWindow(true);Set(window,"macroRepository",new MacroRepository(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"nonexistent-fake-macro-store")));Set(window,"macroFiles",new List<MacroDocument>());
  foreach(int width in new[]{1538,1180})Layout(window,Document(),-1,width,"empty");var kinds=new[]{"key-down","key-up","mouse-down","mouse-up","mouse-wheel","mouse-move","delay"};foreach(string kind in kinds)foreach(int width in new[]{1538,1180})Layout(window,Document(Action(kind)),0,width,kind);var hundred=Document(Enumerable.Range(0,100).Select(i=>Action(i%2==0?"key-down":"key-up")).ToArray());foreach(int width in new[]{1538,1180})Layout(window,hundred,-1,width,"hundred");foreach(int width in new[]{1538,1180})Layout(window,Document(Action("key-down"),Action("key-up")),0,width,"playing",true);Set(window,"macroPlayTask",null);foreach(int width in new[]{1538,1180})Layout(window,Document(),-1,width,"recording",false,true);var longName=Document();longName.Name=String.Concat(Enumerable.Repeat("测试长名称",24));foreach(int width in new[]{1538,1180})Layout(window,longName,-1,width,"long-name");
  var editor=(MacroEditor)Get(window,"macroEditor");editor.Load(Document(Action("key-down"),Action("key-up")));Set(window,"macroSelection",0);Invoke(window,"ShowPage","宏");((TextBox)Get(window,"macroBeforeBox")).Text="999";((Button)Get(window,"macroCancelButton")).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(((TextBox)Get(window,"macroBeforeBox")).Text=="50"&&editor.Current.Actions[0].BeforeMs==50,"cancel restores unsaved parameter values without changing the document");Invoke(window,"InsertMacroAction","delay");Check(editor.Current.Actions.Count==3,"insert remains a real local editor operation");((Button)Get(window,"macroUndoButton")).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(editor.Current.Actions.Count==2,"toolbar undo retains editor semantics");((Button)Get(window,"macroRedoButton")).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(editor.Current.Actions.Count==3,"toolbar redo retains editor semantics");var menu=(ContextMenu)Invoke(window,"BuildMacroOptionsMenu");var positions=menu.Items.OfType<MenuItem>().Single(item=>Convert.ToString(item.Header)=="录制鼠标移动");positions.IsChecked=true;Check((bool)Get(window,"macroPositions"),"relocated recording option preserves its real flag");positions.IsChecked=false;Check(!(bool)Get(window,"macroPositions"),"recording option can still be disabled");Check(!window.IsVisible&&PresentationSource.FromVisual(window)==null&&Get(window,"macroRecordingHook")==null&&Get(window,"macroPlaybackHook")==null,"local editing created no window or input hooks");
